import numpy as np

# Define the crown graph C_{m, n} with n = 7 and m = 7
n = 7
m = 7
graph = np.zeros((m, n))

# Define the coloring of the edges between u_i and v_j
coloring_u_v = np.random.randint(1, 10, size=(m, n))

# Define the coloring of the edges between v_i and v_{(i+1) mod n}
coloring_v_v = np.random.randint(1, 10, size=n)

# Ensure that the edges with a common vertex get different colors
for i in range(m):
    for j in range(n):
        for k in range(n):
            if k != (j + 1) % n:
                graph[i, j] = coloring_u_v[i, j]
                graph[k, j] = coloring_u_v[k, j]
                if graph[i, j] == graph[k, j]:
                    graph[i, j] += 1

# Ensure that the edges with a common vertex get different colors
for i in range(n):
    for j in range(n):
        if j != (i + 1) % n:
            if coloring_v_v[i] == coloring_v_v[j]:
                coloring_v_v[i] += 1

# Print the matrix of colors for the edges between u_i and v_j
print("Matrix of colors for the edges between u_i and v_j:")
print(graph)

# Print the list of colors for the edges between v_i and v_{(i+1) mod n}
print("\nList of colors for the edges between v_i and v_{(i+1) mod n}:")
